+// Sales and variance: what the till says was used against what the ledger
+// says was consumed.
+import { dayOf } from "../dates.js";
+import { listItems } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Per item between two days (inclusive): theoretical use from sales, actual use from consume movements, and the difference (actual - theoretical). */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const theo = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const n of scaled(getRecipe(store, s.recipeId), s.qty)) theo.set(n.itemId, (theo.get(n.itemId) ?? 0) + n.qty);
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return listItems(store)
+    .map((i) => {
+      const theoretical = r3(theo.get(i.id) ?? 0);
+      const used = r3(actual.get(i.id) ?? 0);
+      return { itemId: i.id, name: i.name, unit: i.unit, theoretical, actual: used, difference: r3(used - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
